<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Enable;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Service\Visibility\ThemeAssetVisibilityService;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeAssetEnableUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeAssetVisibilityService $visibility,
        private readonly ThemeAssetWriteGateway $writer,
    ) {
    }

    public function allowEnable(?ThemeAssetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of Enable usecase for Theme asset");
        $span = $this->startSpan("Check allow of Enable usecase for Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetEnableAllowDecision(Allow::allowed('enable', 'Allowed to Theme asset by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function enable(string $uid): ThemeAssetEnableResult
    {
        $this->logDebug("Run Enable usecase for Theme asset");
        $span = $this->startSpan("Run Enable usecase for Theme asset");
        try {
            $ref = new ThemeAssetRef($uid);
            $allow = $this->allowEnable($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to Enable Theme asset');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new ThemeAssetEnableCheck($original));
            $modified = $original->enable();
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ThemeAssetEnableResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
